"use client"

import {
  closestCenter,
  DndContext,
  DragEndEvent,
  DragOverlay,
  DragStartEvent,
  PointerSensor,
  useDraggable,
  useDroppable,
  useSensor,
  useSensors,
} from "@dnd-kit/core"
import { SortableContext, useSortable, verticalListSortingStrategy } from "@dnd-kit/sortable"
import { CSS } from "@dnd-kit/utilities"
import {
  Columns,
  Copy,
  Download,
  Eye,
  FileJson,
  GripVertical,
  Plus,
  Redo2,
  RotateCcw,
  Trash2,
  Undo2,
  Upload,
  X,
} from "lucide-react"

import * as React from "react"
import { useTsLocale } from "@/components/ts-web-ui/locale"
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { ScrollArea } from "@/components/ui/scroll-area"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Separator } from "@/components/ui/separator"
import { Switch } from "@/components/ui/switch"
import { Textarea } from "@/components/ui/textarea"
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

import { TsForm } from "@/components/ts-web-ui/ts-form"
import {
  TsButton,
  TsButtonVariant,
  TsFieldDef,
  TsFieldUpdate,
  TsInfoboxVariant,
} from "@/components/ts-web-ui/ts-form/types"
import { useFormEditorStore, VALID_FIELD_KEY } from "./store"
import { EditorRow, EditorRowItem, EditorTab, GROUPED_FIELD_TYPES } from "./types"

/**
 * TsFormEditor - Visual form builder
 *
 * Provides a complete interface for form creation:
 * - Drag & drop field addition
 * - Support for tabs and single-page mode
 * - Grid layout with multiple fields per row
 * - Real-time form preview
 * - JSON configuration export/import
 */
export function TsFormEditor() {
  const fe = useTsLocale().strings.formEditor
  const {
    form,
    selection,
    activeTabIndex,
    setMode,
    addTab,
    removeTab,
    updateTabLabel,
    setActiveTabIndex,
    addRow,
    removeRow,
    reorderRows,
    addColumnToRow,
    insertColumnAtPosition,
    removeColumnFromRow,
    updateColumnWidth,
    addField,
    removeField,
    renameField,
    updateFieldConfig,
    moveField,
    addButton,
    removeButton,
    moveButton,
    setSelection,
    clearSelection,
    importJson,
    exportJson,
    resetForm,
    undo,
    redo,
    history,
    historyIndex,
  } = useFormEditorStore()

  // UI States
  const [showPreview, setShowPreview] = React.useState(false)
  const [showImportDialog, setShowImportDialog] = React.useState(false)
  const [importJsonText, setImportJsonText] = React.useState("")
  const [importError, setImportError] = React.useState("")
  const [activeDragId, setActiveDragId] = React.useState<string | null>(null)
  const [dragType, setActiveDragType] = React.useState<"palette" | "field" | "row" | null>(null)
  const [eventLog, setEventLog] = React.useState<
    { id: string; time: string; type: string; data: unknown }[]
  >([])
  const previewContainerRef = React.useRef<HTMLDivElement>(null)

  const addLog = React.useCallback((type: string, data: unknown) => {
    setEventLog((prev) => [
      {
        id: Math.random().toString(36).substring(2, 9),
        time: new Date().toLocaleTimeString(),
        type,
        data,
      },
      ...prev.slice(0, 49), // Keep last 50 events
    ])
  }, [])

  // Handle preview events
  React.useEffect(() => {
    if (!showPreview) return

    const handleFieldAction = (e: Event) => {
      const customEvent = e as CustomEvent
      // Only log events from our preview container
      if (previewContainerRef.current?.contains(e.target as Node)) {
        addLog("FIELD_ACTION", customEvent.detail)
      }
    }

    const handleTableAction = (e: Event) => {
      const customEvent = e as CustomEvent
      // Only log events from our preview container
      if (previewContainerRef.current?.contains(e.target as Node)) {
        addLog("TABLE_ACTION", customEvent.detail)
      }
    }

    const handleKeyAction = (e: Event) => {
      const customEvent = e as CustomEvent
      // Only log events from our preview container
      if (previewContainerRef.current?.contains(e.target as Node)) {
        addLog("KEY_ACTION", customEvent.detail)
      }
    }

    window.addEventListener("form-field-action", handleFieldAction)
    window.addEventListener("form-table-action", handleTableAction)
    window.addEventListener("form-key-action", handleKeyAction)

    return () => {
      window.removeEventListener("form-field-action", handleFieldAction)
      window.removeEventListener("form-table-action", handleTableAction)
      window.removeEventListener("form-key-action", handleKeyAction)
    }
  }, [showPreview, addLog])

  // DND setup
  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 5 } }))

  const handleDragStart = (event: DragStartEvent) => {
    const { active } = event
    setActiveDragId(active.id as string)
    setActiveDragType(active.data.current?.type || "field")
  }

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event
    setActiveDragId(null)
    setActiveDragType(null)

    if (!over) return

    // SOURCE: Palette
    if (active.data.current?.source === "palette") {
      const fieldType = active.data.current.fieldType

      // TARGET: Cell
      if (over.data.current?.type === "cell") {
        const { rowIndex, itemIndex } = over.data.current
        addField(fieldType, activeTabIndex, rowIndex, itemIndex)
        return
      }

      // TARGET: Row (add to first empty or end)
      if (over.data.current?.type === "row") {
        const { rowIndex } = over.data.current
        addField(fieldType, activeTabIndex, rowIndex, 0)
        return
      }
    }

    // SOURCE: Field (Moving within form)
    if (active.data.current?.type === "field" && over.data.current?.type === "cell") {
      const from = active.data.current
      const to = over.data.current
      if (
        from.tabIndex !== to.tabIndex ||
        from.rowIndex !== to.rowIndex ||
        from.itemIndex !== to.itemIndex
      ) {
        moveField(
          from.tabIndex,
          from.rowIndex,
          from.itemIndex,
          to.tabIndex,
          to.rowIndex,
          to.itemIndex
        )
      }
      return
    }

    // SOURCE: Row (Reordering)
    if (active.data.current?.type === "row" && over.data.current?.type === "row") {
      if (active.id !== over.id) {
        const rows = getCurrentRows()
        const oldIndex = rows.findIndex((r) => r.id === active.id)
        const newIndex = rows.findIndex((r) => r.id === over.id)
        if (oldIndex !== -1 && newIndex !== -1) {
          reorderRows(activeTabIndex, oldIndex, newIndex)
        }
      }
    }

    // SOURCE: Button (Reordering)
    if (active.data.current?.type === "button-move" && over.data.current?.type === "button-move") {
      const fromIndex = active.data.current.index
      const toIndex = over.data.current.index
      if (fromIndex !== toIndex) {
        moveButton(fromIndex, toIndex)
      }
    }
  }

  // Keyboard shortcuts
  React.useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Ignore if inside an input
      if (["INPUT", "TEXTAREA", "SELECT"].includes((e.target as HTMLElement).tagName)) {
        return
      }

      // Delete - delete selected
      if (e.key === "Delete" || e.key === "Backspace") {
        if (selection.type === "field" && selection.id) {
          removeField(selection.id)
        }
      }

      // Ctrl+Z - undo
      if (e.key === "z" && (e.ctrlKey || e.metaKey) && !e.shiftKey) {
        e.preventDefault()
        undo()
      }

      // Ctrl+Shift+Z or Ctrl+Y - redo
      if (
        (e.key === "z" && (e.ctrlKey || e.metaKey) && e.shiftKey) ||
        (e.key === "y" && (e.ctrlKey || e.metaKey))
      ) {
        e.preventDefault()
        redo()
      }

      // Escape - cancel selection
      if (e.key === "Escape") {
        clearSelection()
      }
    }

    window.addEventListener("keydown", handleKeyDown)
    return () => window.removeEventListener("keydown", handleKeyDown)
  }, [selection, removeField, undo, redo, clearSelection])

  /**
   * Gets rows based on current mode
   */
  const getCurrentRows = (): EditorRow[] => {
    if (form.mode === "single") {
      return form.rows || []
    }
    return form.tabs?.[activeTabIndex]?.rows || []
  }

  /**
   * Processes JSON import
   */
  const handleImport = () => {
    setImportError("")
    const success = importJson(importJsonText)
    if (success) {
      setShowImportDialog(false)
      setImportJsonText("")
    } else {
      setImportError(fe.invalidJsonError)
    }
  }

  /**
   * Copies JSON to clipboard
   */
  const handleCopyJson = () => {
    navigator.clipboard.writeText(exportJson())
  }

  /**
   * Downloads JSON as a file
   */
  const handleDownloadJson = () => {
    const blob = new Blob([exportJson()], { type: "application/json" })
    const url = URL.createObjectURL(blob)
    const a = document.createElement("a")
    a.href = url
    a.download = "form-definition.json"
    a.click()
    URL.revokeObjectURL(url)
  }

  /**
   * Uploads JSON from a file
   */
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return

    const reader = new FileReader()
    reader.onload = (event) => {
      const content = event.target?.result as string
      setImportJsonText(content)
    }
    reader.readAsText(file)
  }

  return (
    <TooltipProvider>
      <div className="flex flex-col h-full">
        {/* Toolbar */}
        <div className="flex items-center justify-between border-b p-2 bg-muted/30">
          <div className="flex items-center gap-2">
            {/* Mode toggle */}
            <Select
              value={form.mode}
              onValueChange={(v: string) => setMode(v as "tabs" | "single")}
            >
              <SelectTrigger className="w-32">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="single">{fe.noTabs}</SelectItem>
                <SelectItem value="tabs">{fe.withTabs}</SelectItem>
              </SelectContent>
            </Select>

            <Separator orientation="vertical" className="h-6" />

            {/* Undo/Redo */}
            <Tooltip>
              <TooltipTrigger asChild>
                <Button variant="ghost" size="icon" onClick={undo} disabled={historyIndex < 0}>
                  <Undo2 className="h-4 w-4" />
                </Button>
              </TooltipTrigger>
              <TooltipContent>{fe.undo}</TooltipContent>
            </Tooltip>

            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={redo}
                  disabled={historyIndex >= history.length - 1}
                >
                  <Redo2 className="h-4 w-4" />
                </Button>
              </TooltipTrigger>
              <TooltipContent>{fe.redo}</TooltipContent>
            </Tooltip>

            <Separator orientation="vertical" className="h-6" />

            {/* Reset */}
            <Tooltip>
              <TooltipTrigger asChild>
                <Button variant="ghost" size="icon" onClick={resetForm}>
                  <RotateCcw className="h-4 w-4" />
                </Button>
              </TooltipTrigger>
              <TooltipContent>{fe.resetForm}</TooltipContent>
            </Tooltip>
          </div>

          <div className="flex items-center gap-2">
            {/* Import */}
            <Dialog open={showImportDialog} onOpenChange={setShowImportDialog}>
              <DialogTrigger asChild>
                <Button variant="outline" size="sm">
                  <Upload className="h-4 w-4 mr-2" />
                  {fe.import}
                </Button>
              </DialogTrigger>
              <DialogContent className="max-w-2xl">
                <DialogHeader>
                  <DialogTitle>{fe.importJsonConfig}</DialogTitle>
                  <DialogDescription>{fe.importDescription}</DialogDescription>
                </DialogHeader>
                <div className="space-y-4">
                  <div className="flex gap-2">
                    <Input
                      type="file"
                      accept=".json"
                      onChange={handleFileUpload}
                      className="flex-1"
                    />
                  </div>
                  <Textarea
                    value={importJsonText}
                    onChange={(e) => setImportJsonText(e.target.value)}
                    placeholder='{"fields": {}, "layout": {}, "buttons": []}'
                    className="min-h-75 font-mono text-sm"
                  />
                  {importError && <p className="text-sm text-destructive">{importError}</p>}
                </div>
                <DialogFooter>
                  <Button variant="outline" onClick={() => setShowImportDialog(false)}>
                    {fe.cancel}
                  </Button>
                  <Button onClick={handleImport}>{fe.import}</Button>
                </DialogFooter>
              </DialogContent>
            </Dialog>

            {/* Export dropdown */}
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="outline" size="sm">
                  <Download className="h-4 w-4 mr-2" />
                  {fe.export}
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent>
                <DropdownMenuItem onClick={handleCopyJson}>
                  <Copy className="h-4 w-4 mr-2" />
                  {fe.copyToClipboard}
                </DropdownMenuItem>
                <DropdownMenuItem onClick={handleDownloadJson}>
                  <FileJson className="h-4 w-4 mr-2" />
                  {fe.downloadAsFile}
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>

            <Separator orientation="vertical" className="h-6" />

            {/* Preview */}
            <Button variant="default" size="sm" onClick={() => setShowPreview(true)}>
              <Eye className="h-4 w-4 mr-2" />
              {fe.preview}
            </Button>
          </div>
        </div>

        {/* Main content */}
        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          onDragStart={handleDragStart}
          onDragEnd={handleDragEnd}
        >
          <div className="flex-1 flex overflow-hidden">
            {/* Sidebar - Component Palette */}
            <div className="w-64 border-r bg-muted/20 flex flex-col min-h-0">
              <div className="p-3 border-b shrink-0">
                <h3 className="font-semibold text-sm">{fe.components}</h3>
              </div>
              <ScrollArea className="flex-1 min-h-0">
                <Accordion
                  type="multiple"
                  defaultValue={Object.keys(GROUPED_FIELD_TYPES)}
                  className="px-2 py-1"
                >
                  {Object.entries(GROUPED_FIELD_TYPES).map(([group, fields]) => (
                    <AccordionItem key={group} value={group} className="border-none">
                      <AccordionTrigger className="py-2 text-sm hover:no-underline">
                        {(fe.fieldGroupLabels as Record<string, string>)[group.toLowerCase()] ??
                          group}
                      </AccordionTrigger>
                      <AccordionContent>
                        <div className="grid grid-cols-2 gap-1 pb-2">
                          {fields.map((field) => (
                            <FieldPaletteItem
                              key={field.type}
                              type={field.type}
                              label={
                                (fe.fieldTypeLabels as Record<string, string>)[
                                  field.type === "button-group" ? "buttonGroup" : field.type
                                ] ?? field.label
                              }
                              icon={field.icon}
                              onAdd={() => {
                                const rows = getCurrentRows()
                                // Add to the first empty slot or new row
                                let added = false
                                for (let ri = 0; ri < rows.length && !added; ri++) {
                                  for (let ii = 0; ii < rows[ri].items.length && !added; ii++) {
                                    if (
                                      rows[ri].items[ii].type === "empty" &&
                                      !rows[ri].items[ii].field
                                    ) {
                                      addField(
                                        field.type as TsFieldDef["type"],
                                        activeTabIndex,
                                        ri,
                                        ii
                                      )
                                      added = true
                                    }
                                  }
                                }
                                if (!added) {
                                  // Add a new row matching the last row's column count,
                                  // then place the widget into its first slot.
                                  const lastRow = rows[rows.length - 1]
                                  const colCount = lastRow ? lastRow.items.length : 1
                                  const newRowIndex = rows.length
                                  addRow(activeTabIndex, undefined, colCount)
                                  addField(
                                    field.type as TsFieldDef["type"],
                                    activeTabIndex,
                                    newRowIndex,
                                    0
                                  )
                                }
                              }}
                            />
                          ))}
                        </div>
                      </AccordionContent>
                    </AccordionItem>
                  ))}
                </Accordion>
              </ScrollArea>
            </div>

            {/* Canvas */}
            <div className="flex-1 bg-slate-50 dark:bg-slate-900 overflow-auto p-6">
              <div className="max-w-4xl mx-auto space-y-4">
                {/* Tabs (if mode === 'tabs') */}
                {form.mode === "tabs" && form.tabs && (
                  <Card>
                    <CardContent className="pt-4">
                      <div className="flex items-center gap-2 flex-wrap">
                        {form.tabs.map((tab: EditorTab, index: number) => (
                          <div
                            key={tab.id}
                            className={cn(
                              "flex items-center gap-1 px-3 py-1.5 rounded-md cursor-pointer border transition-colors",
                              index === activeTabIndex
                                ? "bg-primary text-primary-foreground border-primary"
                                : "bg-muted hover:bg-muted/80 border-transparent"
                            )}
                            onClick={() => setActiveTabIndex(index)}
                          >
                            <Input
                              value={tab.label}
                              onChange={(e) => updateTabLabel(index, e.target.value)}
                              className="h-6 w-24 bg-transparent border-none text-center p-0 focus-visible:ring-0"
                              onClick={(e) => e.stopPropagation()}
                            />
                            {form.tabs && form.tabs.length > 1 && (
                              <Button
                                variant="ghost"
                                size="icon"
                                className="h-5 w-5"
                                onClick={(e) => {
                                  e.stopPropagation()
                                  removeTab(index)
                                }}
                              >
                                <X className="h-3 w-3" />
                              </Button>
                            )}
                          </div>
                        ))}
                        <Button variant="outline" size="sm" onClick={() => addTab()}>
                          <Plus className="h-4 w-4" />
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                )}
                {/* Canvas with rows */}
                <Card>
                  <CardHeader className="pb-2">
                    <CardTitle className="text-base">{fe.formLayout}</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <SortableContext
                      items={getCurrentRows().map((r) => r.id)}
                      strategy={verticalListSortingStrategy}
                    >
                      <div className="space-y-2 min-h-50">
                        {getCurrentRows().map((row, rowIndex) => (
                          <CanvasRow
                            key={row.id}
                            row={row}
                            rowIndex={rowIndex}
                            tabIndex={activeTabIndex}
                            selection={selection}
                            onSelect={setSelection}
                            onRemoveRow={() => removeRow(activeTabIndex, rowIndex)}
                            onAddColumn={() => addColumnToRow(activeTabIndex, rowIndex)}
                            onInsertColumnAt={(itemIndex) =>
                              insertColumnAtPosition(activeTabIndex, rowIndex, itemIndex)
                            }
                            onRemoveColumn={(itemIndex) =>
                              removeColumnFromRow(activeTabIndex, rowIndex, itemIndex)
                            }
                            onUpdateColumnWidth={(itemIndex, width) =>
                              updateColumnWidth(activeTabIndex, rowIndex, itemIndex, width)
                            }
                            fields={form.fields}
                          />
                        ))}

                        {/* Button to add row */}
                        <Button
                          variant="outline"
                          className="w-full border-dashed"
                          onClick={() => addRow(activeTabIndex)}
                        >
                          <Plus className="h-4 w-4 mr-2" />
                          {fe.addRow}
                        </Button>
                      </div>
                    </SortableContext>
                  </CardContent>
                </Card>
                {/* Form Buttons */}
                <Card>
                  <CardHeader className="pb-2">
                    <div className="flex items-center justify-between">
                      <CardTitle className="text-base">{fe.buttons}</CardTitle>
                      <Button variant="outline" size="sm" onClick={addButton}>
                        <Plus className="h-4 w-4 mr-2" />
                        {fe.addButtonLabel}
                      </Button>
                    </div>
                  </CardHeader>
                  <CardContent>
                    <SortableContext
                      items={form.buttons.map((_, i) => `button-${i}`)}
                      strategy={verticalListSortingStrategy}
                    >
                      <div className="flex flex-wrap gap-2">
                        {form.buttons.map((button: TsButton, index: number) => (
                          <SortableButton
                            key={index}
                            button={button}
                            index={index}
                            isSelected={
                              selection.type === "button" && selection.itemIndex === index
                            }
                            onSelect={() =>
                              setSelection({ type: "button", id: "button", itemIndex: index })
                            }
                            onRemove={() => removeButton(index)}
                          />
                        ))}
                      </div>
                    </SortableContext>
                  </CardContent>
                </Card>{" "}
              </div>

              <DragOverlay dropAnimation={null}>
                {activeDragId ? (
                  <div className="bg-primary text-primary-foreground px-4 py-2 rounded-md shadow-2xl opacity-90 cursor-grabbing flex items-center gap-2 border-2 border-primary-foreground/20 min-w-37.5">
                    <GripVertical className="h-4 w-4 shrink-0" />
                    <div className="flex flex-col">
                      <span className="text-[10px] uppercase opacity-70 font-bold leading-none mb-1">
                        {dragType === "palette"
                          ? fe.dragAdding
                          : dragType === "row"
                            ? fe.dragMovingRow
                            : fe.dragMovingField}
                      </span>
                      <span className="text-sm font-medium">
                        {dragType === "palette"
                          ? String(activeDragId).replace("palette-", "")
                          : dragType === "field"
                            ? String(activeDragId).replace("field-", "")
                            : activeDragId.startsWith("button-")
                              ? fe.dragButton
                              : fe.dragRow}
                      </span>
                    </div>
                  </div>
                ) : null}
              </DragOverlay>
            </div>

            {/* Properties Panel */}
            <div className="w-80 border-l bg-background flex flex-col min-h-0">
              <div className="p-3 border-b shrink-0">
                <h3 className="font-semibold text-sm">{fe.properties}</h3>
              </div>
              <ScrollArea className="flex-1 min-h-0">
                <div className="p-3">
                  {(selection.type === "field" && selection.id && form.fields[selection.id]) ||
                  (selection.type === "button" && selection.itemIndex !== undefined) ? (
                    <FieldPropertiesPanel
                      fieldName={selection.id || "button"}
                      config={form.fields[selection.id || ""] || ({} as TsFieldDef)}
                      onRename={(nextFieldName) => renameField(selection.id!, nextFieldName)}
                      onUpdate={(config) => updateFieldConfig(selection.id!, config)}
                      onDelete={() => removeField(selection.id!)}
                    />
                  ) : (
                    <div className="text-sm text-muted-foreground text-center py-10">
                      {fe.selectFieldOrButton}
                    </div>
                  )}
                </div>
              </ScrollArea>
            </div>
          </div>
        </DndContext>

        {/* Preview Dialog */}
        <Dialog open={showPreview} onOpenChange={setShowPreview}>
          <DialogContent
            className="max-w-none w-[98vw] min-w-300 max-h-[95vh] overflow-hidden flex flex-col"
            onEscapeKeyDown={(e) => {
              // Prevent dialog from closing on Escape so that form fields can handle it
              e.preventDefault()
            }}
          >
            <DialogHeader className="shrink-0">
              <DialogTitle>{fe.formPreview}</DialogTitle>
              <DialogDescription>{fe.interactivePreview}</DialogDescription>
            </DialogHeader>
            <div
              ref={previewContainerRef}
              className="h-96 shrink-0 overflow-hidden border rounded-lg p-6 bg-background shadow-sm"
            >
              <TsForm
                fields={form.fields}
                layout={
                  form.mode === "tabs"
                    ? {
                        tabs: form.tabs?.map((t: EditorTab) => ({
                          label: t.label,
                          rows: t.rows.map((r: EditorRow) =>
                            r.items
                              .filter((item: EditorRowItem) => item.field)
                              .map((item: EditorRowItem) => ({
                                field: item.field,
                                width: item.width,
                              }))
                          ),
                        })),
                      }
                    : {
                        rows: form.rows?.map((r: EditorRow) =>
                          r.items
                            .filter((item: EditorRowItem) => item.field)
                            .map((item: EditorRowItem) => ({
                              field: item.field,
                              width: item.width,
                            }))
                        ),
                      }
                }
                buttons={form.buttons}
                onAction={(action, data) => addLog("ACTION", { action, data })}
                onFieldChange={(name, value, data) => addLog("FIELD_CHANGE", { name, value, data })}
                onTabChange={(tab) => addLog("TAB_CHANGE", { tab })}
              />
            </div>
            <div className="mt-4 flex min-h-0 flex-1 flex-col">
              <div className="flex shrink-0 items-center justify-between mb-2">
                <h4 className="font-medium">{fe.eventLog}</h4>
                <Button variant="ghost" size="sm" onClick={() => setEventLog([])}>
                  {fe.clearLog}
                </Button>
              </div>
              <ScrollArea className="flex-1 border rounded-md bg-muted/20 p-2 font-mono text-xs">
                {eventLog.length === 0 ? (
                  <div className="text-muted-foreground text-center py-10">{fe.noEvents}</div>
                ) : (
                  <div className="space-y-1">
                    {eventLog.map((log) => (
                      <div
                        key={log.id}
                        className="flex gap-2 border-b border-muted py-1 last:border-0"
                      >
                        <span className="text-blue-500 shrink-0">[{log.time}]</span>
                        <Badge
                          variant="outline"
                          className="h-4 px-1 text-[10px] uppercase shrink-0"
                        >
                          {log.type}
                        </Badge>
                        <span className="text-foreground break-all">
                          {typeof log.data === "string" ? log.data : JSON.stringify(log.data)}
                        </span>
                      </div>
                    ))}
                  </div>
                )}
              </ScrollArea>
            </div>
          </DialogContent>
        </Dialog>
      </div>
    </TooltipProvider>
  )
}

/**
 * Item in the component palette
 */
function FieldPaletteItem({
  type,
  label,
  icon: Icon,
  onAdd,
}: {
  type: string
  label: string
  icon: React.ElementType
  onAdd: () => void
}) {
  const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
    id: `palette-${type}`,
    data: {
      source: "palette",
      fieldType: type,
      type: "palette",
    },
  })

  return (
    <div
      ref={setNodeRef}
      {...listeners}
      {...attributes}
      className={cn(
        "group flex flex-col items-center justify-center p-2 rounded-md border bg-card hover:border-primary/50 hover:bg-accent transition-all cursor-grab active:cursor-grabbing",
        isDragging && "opacity-50 border-primary"
      )}
      onClick={onAdd}
    >
      <Icon className="h-5 w-5 mb-1 text-muted-foreground group-hover:text-primary" />
      <span className="text-[10px] font-medium text-center leading-tight">{label}</span>
