}

/**
 * Row on the canvas
 */
function CanvasRow({
  row,
  rowIndex,
  tabIndex,
  selection,
  onSelect,
  onRemoveRow,
  onAddColumn,
  onInsertColumnAt,
  onRemoveColumn,
  onUpdateColumnWidth,
  fields,
}: {
  row: EditorRow
  rowIndex: number
  tabIndex: number
  selection: { type: string | null; id: string | null; rowIndex?: number; itemIndex?: number }
  onSelect: (selection: {
    type: "field"
    id: string
    tabIndex: number
    rowIndex: number
    itemIndex: number
  }) => void
  onRemoveRow: () => void
  onAddColumn: () => void
  onInsertColumnAt: (itemIndex: number) => void
  onRemoveColumn: (itemIndex: number) => void
  onUpdateColumnWidth: (itemIndex: number, width: string) => void
  fields: Record<string, TsFieldDef>
}) {
  const fe = useTsLocale().strings.formEditor
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: row.id,
    data: {
      type: "row",
      rowIndex,
    },
  })

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  }

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={cn(
        "group flex items-stretch gap-2 p-2 border rounded-md bg-card hover:border-primary/50 transition-colors",
        isDragging && "opacity-50 border-primary z-50"
      )}
    >
      {/* Row grip */}
      <div
        className="flex items-center text-muted-foreground cursor-grab active:cursor-grabbing"
        {...listeners}
        {...attributes}
      >
        <GripVertical className="h-4 w-4" />
      </div>

      {/* Grid items */}
      <div
        className="flex-1 grid gap-2"
        style={{ gridTemplateColumns: row.items.map((i) => i.width || "1fr").join(" ") }}
      >
        {row.items.map((item, itemIndex) => (
          <CanvasCell
            key={item.id}
            item={item}
            tabIndex={tabIndex}
            rowIndex={rowIndex}
            itemIndex={itemIndex}
            isSelected={selection.type === "field" && selection.id === item.field}
            onInsertBefore={() => onInsertColumnAt(itemIndex)}
            onSelect={() => {
              if (item.field) {
                onSelect({ type: "field", id: item.field, tabIndex, rowIndex, itemIndex })
              }
            }}
            onUpdateWidth={(width) => onUpdateColumnWidth(itemIndex, width)}
            fieldConfig={item.field ? fields[item.field] : undefined}
            showRemove={row.items.length > 1}
            onRemove={() => onRemoveColumn(itemIndex)}
          />
        ))}
      </div>

      {/* Row actions */}
      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
        <Tooltip>
          <TooltipTrigger asChild>
            <Button variant="ghost" size="icon" className="h-7 w-7" onClick={onAddColumn}>
              <Columns className="h-3 w-3" />
            </Button>
          </TooltipTrigger>
          <TooltipContent>{fe.addColumn}</TooltipContent>
        </Tooltip>
        <Tooltip>
          <TooltipTrigger asChild>
            <Button
              variant="ghost"
              size="icon"
              className="h-7 w-7 text-destructive"
              onClick={onRemoveRow}
            >
              <Trash2 className="h-3 w-3" />
            </Button>
          </TooltipTrigger>
          <TooltipContent>{fe.deleteRow}</TooltipContent>
        </Tooltip>
      </div>
    </div>
  )
}

/**
 * Cell in a row (contains a field or is empty)
 */
function CanvasCell({
  item,
  isSelected,
  onInsertBefore,
  onSelect,
  onUpdateWidth,
  fieldConfig,
  showRemove,
  onRemove,
  tabIndex,
  rowIndex,
  itemIndex,
}: {
  item: EditorRowItem
  isSelected: boolean
  onInsertBefore: () => void
  onSelect: () => void
  onUpdateWidth: (width: string) => void
  fieldConfig?: TsFieldDef
  showRemove: boolean
  onRemove: () => void
  tabIndex: number
  rowIndex: number
  itemIndex: number
}) {
  const fe = useTsLocale().strings.formEditor
  const { setNodeRef: setDroppableRef, isOver } = useDroppable({
    id: item.id,
    data: {
      type: "cell",
      tabIndex,
      rowIndex,
      itemIndex,
    },
  })

  const isEmpty = !item.field || item.type === "empty"

  const {
    attributes,
    listeners,
    setNodeRef: setDraggableRef,
    isDragging,
  } = useDraggable({
    id: `field-${item.field || item.id}`,
    data: {
      type: "field",
      tabIndex,
      rowIndex,
      itemIndex,
      fieldId: item.field,
    },
    disabled: isEmpty,
  })

  return (
    <div
      ref={setDroppableRef}
      className={cn(
        "group relative min-h-15 p-2 border rounded transition-all cursor-pointer",
        isEmpty ? "border-dashed bg-muted/30 hover:bg-muted/50" : "bg-card hover:border-primary/50",
        isSelected && "ring-2 ring-primary border-primary",
        isOver && "bg-primary/10 border-primary border-solid scale-[1.02] shadow-sm",
        isDragging && "opacity-50"
      )}
      onClick={onSelect}
    >
      <div className="absolute top-1 left-1 z-20 opacity-0 group-hover:opacity-100 group-focus-within:opacity-100 transition-opacity">
        <Tooltip>
          <TooltipTrigger asChild>
            <Button
              variant="secondary"
              size="icon"
              className="h-5 w-5"
              aria-label="Insert column before"
              onClick={(e) => {
                e.stopPropagation()
                onInsertBefore()
              }}
            >
              <Plus className="h-3 w-3" />
            </Button>
          </TooltipTrigger>
          <TooltipContent>{fe.insertColumnBefore}</TooltipContent>
        </Tooltip>
      </div>

      {showRemove && (
        <div className="absolute top-1 right-1 z-20 opacity-0 group-hover:opacity-100 group-focus-within:opacity-100 transition-opacity">
          <Button
            variant="secondary"
            size="icon"
            className="h-5 w-5 text-destructive"
            aria-label="Remove column"
            onClick={(e) => {
              e.stopPropagation()
              onRemove()
            }}
          >
            <X className="h-3 w-3" />
          </Button>
        </div>
      )}

      <div
        ref={setDraggableRef}
        {...listeners}
        {...attributes}
        className={cn("h-full w-full", !isEmpty && "cursor-grab active:cursor-grabbing")}
      >
        {isEmpty ? (
          <div className="flex items-center justify-center h-full text-muted-foreground text-sm">
            <Plus className="h-4 w-4 mr-1" />
            {fe.dragFieldHere}
          </div>
        ) : (
          <div className="space-y-1">
            <div className="flex items-center justify-between">
              <span className="font-medium text-sm truncate">
                {(fieldConfig?.label as string) || item.field}
              </span>
            </div>
            <Badge variant="secondary" className="text-xs">
              {fieldConfig?.type || "field"}
            </Badge>
          </div>
        )}
      </div>

      {/* Width selector */}
      {!isEmpty && (
        <div className="absolute bottom-1 right-1 z-10" onClick={(e) => e.stopPropagation()}>
          <Select value={item.width || "1fr"} onValueChange={onUpdateWidth}>
            <SelectTrigger className="h-5 w-16 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="1fr">1fr</SelectItem>
              <SelectItem value="2fr">2fr</SelectItem>
              <SelectItem value="3fr">3fr</SelectItem>
              <SelectItem value="100px">100px</SelectItem>
              <SelectItem value="150px">150px</SelectItem>
              <SelectItem value="200px">200px</SelectItem>
              <SelectItem value="300px">300px</SelectItem>
            </SelectContent>
          </Select>
        </div>
      )}
    </div>
  )
}

/**
 * Field properties panel
 */
function FieldPropertiesPanel({
  fieldName,
  config,
  onRename,
  onUpdate,
  onDelete,
}: {
  fieldName: string
  config: TsFieldDef
  onRename: (nextFieldName: string) => boolean
  onUpdate: (config: TsFieldUpdate) => void
  onDelete: () => void
}) {
  const fe = useTsLocale().strings.formEditor
  const { form, selection, updateButton, removeButton } = useFormEditorStore()
  const [fieldNameDraft, setFieldNameDraft] = React.useState(fieldName)
  const [renameError, setRenameError] = React.useState<string | null>(null)

  React.useEffect(() => {
    setFieldNameDraft(fieldName)
    setRenameError(null)
  }, [fieldName])

  // If a button is selected, show button properties
  if (selection.type === "button" && selection.itemIndex !== undefined) {
    const button = form.buttons[selection.itemIndex]
    if (!button) return null

    return (
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <Badge>{fe.buttonLabel}</Badge>
          <Button
            variant="destructive"
            size="sm"
            onClick={() => {
              removeButton(selection.itemIndex!)
            }}
          >
            <Trash2 className="h-3 w-3 mr-1" />
            {fe.delete}
          </Button>
        </div>

        <div className="space-y-2">
          <Label>{fe.position}</Label>
          <Select
            value={button.position || "right"}
            onValueChange={(v) =>
              updateButton(selection.itemIndex!, { position: v as "left" | "center" | "right" })
            }
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="left">{fe.positionLeft}</SelectItem>
              <SelectItem value="center">{fe.positionCenter}</SelectItem>
              <SelectItem value="right">{fe.positionRight}</SelectItem>
            </SelectContent>
          </Select>
        </div>

        <div className="space-y-2">
          <Label>{fe.label}</Label>
          <Input
            value={button.label}
            onChange={(e) => updateButton(selection.itemIndex!, { label: e.target.value })}
          />
        </div>

        <div className="space-y-2">
          <Label>{fe.action}</Label>
          <Input
            value={button.action}
            onChange={(e) => updateButton(selection.itemIndex!, { action: e.target.value })}
          />
        </div>

        <div className="space-y-2">
          <Label>{fe.iconLucideName}</Label>
          <Input
            value={button.icon || ""}
            onChange={(e) => updateButton(selection.itemIndex!, { icon: e.target.value })}
            placeholder={fe.actionPlaceholder}
          />
        </div>

        <div className="space-y-2">
          <Label>{fe.variant}</Label>
          <Select
            value={button.variant || "default"}
            onValueChange={(v) =>
              updateButton(selection.itemIndex!, { variant: v as TsButton["variant"] })
            }
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="default">{fe.variantDefault}</SelectItem>
              <SelectItem value="primary">{fe.variantPrimaryBlue}</SelectItem>
              <SelectItem value="secondary">{fe.variantSecondary}</SelectItem>
              <SelectItem value="success">{fe.variantSuccessGreen}</SelectItem>
              <SelectItem value="warning">{fe.variantWarningAmber}</SelectItem>
              <SelectItem value="danger">{fe.variantDangerRed}</SelectItem>
              <SelectItem value="outline">{fe.variantOutline}</SelectItem>
              <SelectItem value="ghost">{fe.variantGhost}</SelectItem>
              <SelectItem value="link">{fe.variantLink}</SelectItem>
            </SelectContent>
          </Select>
        </div>

        <Separator />

        <div className="space-y-3">
          <h4 className="font-medium text-sm">{fe.confirmationDialog}</h4>
          <div className="flex items-center justify-between">
            <Label className="text-xs">{fe.confirmEnabled}</Label>
            <Switch
              checked={!!button.confirmation}
              onCheckedChange={(checked) => {
                if (checked) {
                  updateButton(selection.itemIndex!, {
                    confirmation: {
                      title: "Are you sure?",
                      text: "This action cannot be undone.",
                      buttons: [
                        { action: "cancel", label: "No", position: "right" },
                        {
                          action: "confirm",
                          label: "Yes",
                          variant: "destructive",
                          confirm: true,
                          position: "right",
                        },
                      ],
                    },
                  })
                } else {
                  updateButton(selection.itemIndex!, { confirmation: undefined })
                }
              }}
            />
          </div>

          {button.confirmation && (
            <>
              <div className="space-y-1">
                <Label className="text-xs">{fe.title}</Label>
                <Input
                  value={button.confirmation.title}
                  onChange={(e) =>
                    updateButton(selection.itemIndex!, {
                      confirmation: { ...button.confirmation!, title: e.target.value },
                    })
                  }
                />
              </div>
              <div className="space-y-1">
                <Label className="text-xs">{fe.message}</Label>
                <Textarea
                  value={button.confirmation.text}
                  onChange={(e) =>
                    updateButton(selection.itemIndex!, {
                      confirmation: { ...button.confirmation!, text: e.target.value },
                    })
                  }
                  rows={2}
                />
              </div>
              <div className="space-y-1">
                <Label className="text-xs">{fe.confirmButtonsJson}</Label>
                <Textarea
                  value={JSON.stringify(button.confirmation.buttons, null, 2)}
                  onChange={(e) => {
                    try {
                      updateButton(selection.itemIndex!, {
                        confirmation: {
                          ...button.confirmation!,
                          buttons: JSON.parse(e.target.value),
                        },
                      })
                    } catch {
                      /* ignore */
                    }
                  }}
                  rows={4}
                  className="font-mono text-[10px]"
                />
              </div>
            </>
          )}
        </div>
      </div>
    )
  } // Cast to TsFieldUpdate for reading optional properties that not every field type carries
  // (e.g. placeholder on checkbox). Type-specific properties are accessed via narrowed config below.
  const configProps = config as TsFieldUpdate

  const validateFieldName = (value: string): string | null => {
    const trimmedName = value.trim()

    if (!trimmedName) {
      return fe.fieldIdRequired
    }

    if (!VALID_FIELD_KEY.test(trimmedName)) {
      return fe.fieldIdInvalid
    }

    if (trimmedName !== fieldName && form.fields[trimmedName]) {
      return fe.fieldIdNotUnique
    }

    return null
  }

  const commitFieldRename = () => {
    const trimmedName = fieldNameDraft.trim()

    if (trimmedName === fieldName) {
      setRenameError(null)
      return
    }

    const validationError = validateFieldName(trimmedName)

    if (validationError) {
      setRenameError(validationError)
      return
    }

    const success = onRename(trimmedName)

    if (!success) {
      setRenameError(fe.fieldIdRenameFailed)
      return
    }

    setRenameError(null)
  }

  return (
    <div className="space-y-4">
      {/* Basic info */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <Badge>{config.type}</Badge>
          <Button variant="destructive" size="sm" onClick={onDelete}>
            <Trash2 className="h-3 w-3 mr-1" />
            {fe.delete}
          </Button>
        </div>

        <div className="space-y-2">
          <Label>{fe.fieldId}</Label>
          <Input
            aria-describedby={renameError ? "field-id-error" : undefined}
            aria-invalid={!!renameError}
            value={fieldNameDraft}
            onChange={(e) => {
              const nextValue = e.target.value
              setFieldNameDraft(nextValue)
              setRenameError(validateFieldName(nextValue))
            }}
            onBlur={commitFieldRename}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault()
                commitFieldRename()
              }

              if (e.key === "Escape") {
                e.preventDefault()
                setFieldNameDraft(fieldName)
                setRenameError(null)
              }
            }}
            className="font-mono text-sm"
          />
          {renameError ? (
            <p id="field-id-error" className="text-xs text-destructive" role="alert">
              {renameError}
            </p>
          ) : null}
        </div>

        <div className="space-y-2">
          <Label>{fe.label}</Label>
          <Input
            value={(config.label as string) || ""}
            onChange={(e) => onUpdate({ label: e.target.value })}
          />
        </div>

        <div className="space-y-2">
          <Label>{fe.placeholder}</Label>
          <Input
            value={(configProps.placeholder as string) || ""}
            onChange={(e) => onUpdate({ placeholder: e.target.value })}
          />
        </div>

        <div className="space-y-2">
          <Label>{fe.hint}</Label>
          <Input
            value={(config.hint as string) || ""}
            onChange={(e) => onUpdate({ hint: e.target.value })}
          />
        </div>
      </div>

      <Separator />

      {/* States */}
      <div className="space-y-3">
        <h4 className="font-medium text-sm">{fe.states}</h4>

        <div className="flex items-center justify-between">
          <Label>{fe.required}</Label>
          <Switch
            checked={!!config.required}
            onCheckedChange={(checked: boolean) => onUpdate({ required: checked })}
          />
        </div>

        <div className="flex items-center justify-between">
          <Label>{fe.disabled}</Label>
          <Switch
            checked={!!config.disabled}
            onCheckedChange={(checked: boolean) => onUpdate({ disabled: checked })}
          />
        </div>

        <div className="flex items-center justify-between">
          <Label>{fe.readOnly}</Label>
          <Switch
            checked={!!config.readonly}
            onCheckedChange={(checked: boolean) => onUpdate({ readonly: checked })}
          />
        </div>

        {config.type !== "infobox" && config.type !== "markdown" && (
          <>
            <div className="flex items-center justify-between">
              <Label>{fe.selectAllOnFocus}</Label>
              <Switch
                checked={!!configProps.selectAllOnFocus}
                onCheckedChange={(checked: boolean) => onUpdate({ selectAllOnFocus: checked })}
              />
            </div>

            <div className="space-y-2">
              <Label>{fe.enterAction}</Label>
              <Input
                value={(configProps.enterAction as string) || ""}
                onChange={(e) => onUpdate({ enterAction: e.target.value })}
                placeholder={fe.enterActionPlaceholder}
              />
            </div>

            <div className="space-y-2">
              <Label>{fe.escapeAction}</Label>
              <Input
                value={(configProps.escapeAction as string) || ""}
                onChange={(e) => onUpdate({ escapeAction: e.target.value })}
                placeholder={fe.escapeActionPlaceholder}
              />
            </div>
          </>
        )}

        <div className="flex items-center justify-between">
          <Label>{fe.hidden}</Label>
          <Switch
            checked={!!config.hidden}
            onCheckedChange={(checked: boolean) => onUpdate({ hidden: checked })}
          />
        </div>

        <div className="flex items-center justify-between">
          <Label>{fe.autoFocus}</Label>
          <Switch
            checked={!!configProps.autofocus}
            onCheckedChange={(checked: boolean) => onUpdate({ autofocus: checked })}
          />
        </div>

        <div className="flex items-center justify-between">
          <Label>{fe.hideLabel}</Label>
          <Switch
            checked={!!configProps.hideLabel}
            onCheckedChange={(checked: boolean) => onUpdate({ hideLabel: checked })}
          />
        </div>

        <div className="flex items-center justify-between">
          <Label>{fe.excludeFromSubmit}</Label>
          <Switch
            checked={!!configProps.excludeFromSubmit}
            onCheckedChange={(checked: boolean) => onUpdate({ excludeFromSubmit: checked })}
          />
        </div>
      </div>

      {/* Type-specific properties */}
      {(config.type === "number" || config.type === "slider") && (
        <>
          <Separator />
          <div className="space-y-3">
            <h4 className="font-medium text-sm">{fe.numericSettings}</h4>
            <div className="grid grid-cols-3 gap-2">
              <div className="space-y-1">
                <Label className="text-xs">{fe.min}</Label>
                <Input
                  type="number"
                  value={(config.min as number) ?? ""}
                  onChange={(e) =>
                    onUpdate({ min: e.target.value ? Number(e.target.value) : undefined })
                  }
                />
              </div>
              <div className="space-y-1">
                <Label className="text-xs">{fe.max}</Label>
                <Input
                  type="number"
                  value={(config.max as number) ?? ""}
                  onChange={(e) =>
                    onUpdate({ max: e.target.value ? Number(e.target.value) : undefined })
                  }
                />
              </div>
              <div className="space-y-1">
                <Label className="text-xs">{fe.step}</Label>
                <Input
                  type="number"
                  value={(config.step as number) ?? ""}
                  onChange={(e) =>
                    onUpdate({ step: e.target.value ? Number(e.target.value) : undefined })
                  }
                />
              </div>
            </div>
            {config.type === "number" && (
              <div className="space-y-1">
                <Label className="text-xs">{fe.roundTo}</Label>
                <Input
                  type="number"
                  value={(config.roundTo as number) ?? ""}
                  onChange={(e) =>
                    onUpdate({ roundTo: e.target.value ? Number(e.target.value) : undefined })
                  }
                />
              </div>
            )}
          </div>
        </>
      )}

      {config.type === "textarea" && (
        <>
          <Separator />
          <div className="space-y-2">
            <Label>{fe.rowCount}</Label>
