/**
 * Sortable item for form buttons
 */
function SortableButton({
  button,
  index,
  isSelected,
  onSelect,
  onRemove,
}: {
  button: TsButton
  index: number
  isSelected: boolean
  onSelect: () => void
  onRemove: () => void
}) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: `button-${index}`,
    data: {
      type: "button-move",
      index,
    },
  })

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  }

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={cn("flex items-center gap-1 group relative", isDragging && "opacity-50 z-50")}
    >
      <Badge
        variant="outline"
        className={cn(
          "py-1.5 px-3 cursor-grab active:cursor-grabbing hover:border-primary transition-colors flex items-center gap-2",
          isSelected ? "border-primary ring-1 ring-primary" : ""
        )}
        onClick={(e) => {
          e.stopPropagation()
          onSelect()
        }}
        {...attributes}
        {...listeners}
      >
        <GripVertical className="h-3 w-3 text-muted-foreground" />
        {button.label}
        <Button
          variant="ghost"
          size="icon"
          className="h-4 w-4 ml-1 opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer"
          onClick={(e) => {
            e.stopPropagation()
            onRemove()
          }}
        >
          <X className="h-3 w-3" />
        </Button>
      </Badge>
    </div>
  )
}

