export const GROUPED_FIELD_TYPES = AVAILABLE_FIELD_TYPES.reduce(
  (acc, field) => {
    if (!acc[field.group]) {
      acc[field.group] = []
    }
    acc[field.group].push(field)
    return acc
  },
  {} as Record<string, typeof AVAILABLE_FIELD_TYPES>
)
